import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"in 与 exists","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/basic/in-exists.md","filePath":"database/mysql/basic/in-exists.md"}`),a={name:`database/mysql/basic/in-exists.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="in-与-exists" tabindex="-1">in 与 exists <a class="header-anchor" href="#in-与-exists" aria-label="Permalink to “in 与 exists”">​</a></h1><ul><li>在 MySQL 中，WHERE IN 和 EXISTS 都用于在查询中引入子查询，实现 “根据子查询结果筛选主查询记录” 的功能，但两者的执行逻辑和适用场景有显著区别。</li></ul><h2 id="in-原理" tabindex="-1">in 原理 <a class="header-anchor" href="#in-原理" aria-label="Permalink to “in 原理”">​</a></h2><div class="language-sql" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 字段 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 主表</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 主表字段 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (子查询);</span></span></code></pre></div><ul><li>执行流程 <ul><li>先执行子查询，得到一个单列的结果集（如 (1, 2, 3)）。</li><li>主查询遍历每条记录，判断指定字段的值是否在子查询的结果集中，若存在则保留该记录。</li></ul></li></ul><h2 id="exists-原理" tabindex="-1">exists 原理 <a class="header-anchor" href="#exists-原理" aria-label="Permalink to “exists 原理”">​</a></h2><div class="language-sql" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 字段 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 主表</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (子查询);</span></span></code></pre></div><ul><li>执行流程 <ul><li>主查询遍历每条记录，将当前记录的字段值传入子查询。</li><li>子查询根据主表字段进行关联查询，若返回至少 1 条记录，则 EXISTS 为 TRUE，主查询保留该记录；否则过滤。</li></ul></li></ul><h2 id="核心对比" tabindex="-1">核心对比 <a class="header-anchor" href="#核心对比" aria-label="Permalink to “核心对比”">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>in</th><th>exists</th></tr></thead><tbody><tr><td>执行流程</td><td>先执行子查询，得到结果集；<br>主查询遍历主表判断字段值是否在结果集中</td><td>主查询遍历主表，将当前记录的字段值传入子查询<br>子查询根据主表字段进行关联查询，若返回至少 1 条记录，则 EXISTS 为 TRUE</td></tr><tr><td>子查询结果大小影响</td><td>子查询结果集越大，性能越差（需比对所有值）</td><td>子查询只需返回 1 条记录即可，结果集大小影响小</td></tr><tr><td>关联关系</td><td>子查询可独立执行（不依赖主表）</td><td>子查询必须关联主表字段（否则无意义）</td></tr><tr><td>空值处理</td><td>若子查询返回 NULL，IN 会返回 FALSE</td><td>子查询返回 NULL 时，EXISTS 仍可能为 TRUE</td></tr></tbody></table><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>当子查询结果集较小时，IN 更高效</li><li>当子查询结果集较大时，EXISTS 更高效</li><li>EXISTS 更适合 “主表小、子表大” 的场景</li><li>IN 适合 “子表小、主表大” 的场景</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>若子查询返回 NULL，IN 会返回 FALSE，而 EXISTS 仍可能为 TRUE（取决于主表记录）。</li><li>若子查询返回空集（无匹配记录），IN 会返回 FALSE，而 EXISTS 会返回 FALSE。</li></ul>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};